  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nenum Role {\n  OWNER\n  EMPLOYEE\n}\n\nenum ProductType {\n  TABLET\n  CAPSULE\n  SYRUP\n  INJECTION\n  CREAM\n  DROPS\n  OINTMENT\n  POWDER\n  OTHERS\n}\n\nenum ScheduleDivision {\n  GENERAL\n  SCHEDULE_H\n  SCHEDULE_H1\n  SCHEDULE_X\n}\n\nenum PaymentMethod {\n  CASH\n  UPI\n  CARD\n  CREDIT\n}\n\nenum PartyType {\n  CUSTOMER\n  SUPPLIER\n}\n\nenum TransactionType {\n  DEBIT\n  CREDIT\n}\n\nmodel User {\n  id          String      @id @default(uuid())\n  firebaseUid String      @unique\n  name        String\n  email       String      @unique\n  role        Role        @default(EMPLOYEE)\n  designation String?\n  isActive    Boolean     @default(true)\n  isApproved  Boolean     @default(true)\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @default(now()) @updatedAt\n  salesBills  SalesBill[]\n\n  @@map(\"users\")\n}\n\nmodel Customer {\n  id            String        @id @default(uuid())\n  name          String\n  phone         String?\n  email         String?\n  address       String?\n  gstNumber     String?\n  doctorName    String?\n  isDeleted     Boolean       @default(false)\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @default(now()) @updatedAt\n  salesBills    SalesBill[]\n  ledgerEntries LedgerEntry[]\n\n  @@map(\"customers\")\n}\n\nmodel Party {\n  id            String         @id @default(uuid())\n  name          String\n  phone         String?\n  email         String?\n  address       String?\n  gstNumber     String?\n  dlNumber      String?\n  isDeleted     Boolean        @default(false)\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @default(now()) @updatedAt\n  purchaseBills PurchaseBill[]\n  ledgerEntries LedgerEntry[]\n\n  @@map(\"parties\")\n}\n\nmodel Product {\n  id                  String           @id @default(uuid())\n  name                String\n  genericName         String?\n  companyName         String?\n  hsnCode             String\n  gstPercent          Float            @default(12.0)\n  mrp                 Float?           @default(0.0)\n  purchaseRate        Float?           @default(0.0)\n  productType         ProductType      @default(TABLET)\n  division            ScheduleDivision @default(GENERAL)\n  packSize            Int              @default(1)\n  packUnit            String           @default(\"Strip\")\n  contentUnit         String           @default(\"Tablet\")\n  requiresColdStorage Boolean          @default(false)\n  lowStockThreshold   Float            @default(1.0)\n  isActive            Boolean          @default(true)\n  isDeleted           Boolean          @default(false)\n  createdAt           DateTime         @default(now())\n  updatedAt           DateTime         @default(now()) @updatedAt\n\n  batches           InventoryBatch[]\n  salesBillItems    SalesBillItem[]\n  purchaseBillItems PurchaseBillItem[]\n\n  @@map(\"products\")\n}\n\nmodel InventoryBatch {\n  id                 String   @id @default(uuid())\n  productId          String\n  product            Product  @relation(fields: [productId], references: [id], onDelete: Restrict)\n  batchNumber        String\n  expiryDate         DateTime\n  quantity           Float // Total content units\n  mrp                Float // Price per pack\n  purchaseRate       Float // Cost per pack\n  purchaseDate       DateTime @default(now())\n  purchaseBillId     String?\n  isManualAdjustment Boolean  @default(false)\n  adjustmentReason   String?\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @default(now()) @updatedAt\n\n  salesBillItems SalesBillItem[]\n\n  @@index([productId, expiryDate])\n  @@index([batchNumber])\n  @@map(\"inventory_batches\")\n}\n\nmodel PurchaseBill {\n  id            String   @id @default(uuid())\n  invoiceNumber String\n  partyId       String\n  party         Party    @relation(fields: [partyId], references: [id], onDelete: Restrict)\n  purchaseDate  DateTime @default(now())\n  subtotal      Float\n  taxTotal      Float\n  grandTotal    Float\n  isPaid        Boolean  @default(false)\n  isDeleted     Boolean  @default(false)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @default(now()) @updatedAt\n\n  items         PurchaseBillItem[]\n  ledgerEntries LedgerEntry[]\n\n  @@unique([partyId, invoiceNumber])\n  @@index([partyId])\n  @@index([purchaseDate])\n  @@map(\"purchase_bills\")\n}\n\nmodel PurchaseBillItem {\n  id             String       @id @default(uuid())\n  purchaseBillId String\n  purchaseBill   PurchaseBill @relation(fields: [purchaseBillId], references: [id], onDelete: Cascade)\n  productId      String\n  product        Product      @relation(fields: [productId], references: [id])\n  batchNumber    String\n  expiryDate     DateTime\n  quantity       Float\n  freeQuantity   Float        @default(0)\n  purchaseRate   Float\n  mrp            Float\n  taxPercent     Float\n  totalAmount    Float\n\n  @@map(\"purchase_bill_items\")\n}\n\nmodel SalesBill {\n  id             String        @id @default(uuid())\n  invoiceNumber  Int           @default(autoincrement())\n  customerId     String?\n  customer       Customer?     @relation(fields: [customerId], references: [id])\n  customerName   String?\n  customerPhone  String?\n  doctorName     String?\n  notes          String?\n  userId         String\n  user           User          @relation(fields: [userId], references: [id])\n  paymentMethod  PaymentMethod\n  subtotal       Float\n  taxTotal       Float\n  discount       Float         @default(0)\n  isRoundOff     Boolean       @default(true)\n  roundOffAmount Float         @default(0)\n  grandTotal     Float\n  amountPaid     Float\n  isSettled      Boolean       @default(false)\n  isDeleted      Boolean       @default(false)\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @default(now()) @updatedAt\n\n  items         SalesBillItem[]\n  ledgerEntries LedgerEntry[]\n\n  @@index([customerId])\n  @@index([createdAt])\n  @@map(\"sales_bills\")\n}\n\nmodel SalesBillItem {\n  id          String         @id @default(uuid())\n  salesBillId String\n  salesBill   SalesBill      @relation(fields: [salesBillId], references: [id], onDelete: Cascade)\n  productId   String\n  product     Product        @relation(fields: [productId], references: [id])\n  batchId     String\n  batch       InventoryBatch @relation(fields: [batchId], references: [id])\n  quantity    Float\n  unitPrice   Float\n  taxPercent  Float\n  totalAmount Float\n\n  @@map(\"sales_bill_items\")\n}\n\nmodel LedgerEntry {\n  id              String          @id @default(uuid())\n  partyType       PartyType\n  customerId      String?\n  customer        Customer?       @relation(fields: [customerId], references: [id])\n  partyId         String?\n  party           Party?          @relation(fields: [partyId], references: [id])\n  transactionType TransactionType\n  amount          Float\n  salesBillId     String?\n  salesBill       SalesBill?      @relation(fields: [salesBillId], references: [id])\n  purchaseBillId  String?\n  purchaseBill    PurchaseBill?   @relation(fields: [purchaseBillId], references: [id])\n  paymentMethod   PaymentMethod?\n  description     String?\n  isSettled       Boolean         @default(false)\n  createdAt       DateTime        @default(now())\n  updatedAt       DateTime        @default(now()) @updatedAt\n\n  @@index([partyId])\n  @@index([customerId])\n  @@map(\"ledger_entries\")\n}\n",
